insert into public.professionals (id, name, title, specialty, years, languages, focus, types, fees, schedule, bio, verified_at, active) values
  ('funmi-adeyemi', 'Funmi Adeyemi', 'Registered dietitian', 'dietitian', 9, array['English', 'Yorùbá']::text[], array['diabetes', 'weight', 'heart']::text[], array['video', 'voice', 'chat']::text[], '{"video":8000,"voice":7000,"chat":5000}'::jsonb, '{"0":[9,17],"1":[9,17],"2":[12,19],"3":[9,17],"4":[9,14]}'::jsonb, 'Funmi helps people manage diabetes and lose weight with Nigerian food they already love. She believes in small changes that fit real family life and real budgets.', now(), true),
  ('chidi-okafor', 'Chidi Okafor', 'Registered dietitian', 'dietitian', 6, array['English', 'Igbo', 'Pidgin']::text[], array['sports', 'weight', 'kidney']::text[], array['video', 'voice', 'chat']::text[], '{"video":7500,"voice":6500,"chat":4500}'::jsonb, '{"1":[10,18],"2":[10,18],"3":[10,18],"5":[9,13]}'::jsonb, 'Chidi works with active people, students and anyone managing kidney health. Expect practical meal ideas and clear portion guidance.', now(), true),
  ('amina-bello', 'Amina Bello', 'Registered dietitian', 'dietitian', 11, array['English', 'Hausa']::text[], array['pregnancy', 'children', 'pcos']::text[], array['video', 'voice', 'chat']::text[], '{"video":9000,"voice":8000,"chat":5500}'::jsonb, '{"0":[8,14],"2":[8,14],"4":[8,16],"5":[9,12]}'::jsonb, 'Amina specialises in nutrition before, during and after pregnancy, feeding young children, and PCOS. She is known for her calm, reassuring style.', now(), true),
  ('tunde-balogun', 'Dr Tunde Balogun', 'Family doctor', 'doctor', 14, array['English', 'Yorùbá', 'Pidgin']::text[], array['hypertension', 'diabetes', 'general']::text[], array['video', 'voice', 'chat']::text[], '{"video":12000,"voice":10000,"chat":7000}'::jsonb, '{"0":[16,21],"1":[16,21],"2":[16,21],"3":[16,21],"5":[10,15]}'::jsonb, 'Dr Balogun looks after adults with high blood pressure and diabetes, and helps with everyday health concerns, test results and prescriptions.', now(), true),
  ('ngozi-eze', 'Dr Ngozi Eze', 'General practitioner', 'doctor', 8, array['English', 'Igbo']::text[], array['womens', 'general', 'pregnancy']::text[], array['video', 'voice', 'chat']::text[], '{"video":11000,"voice":9500,"chat":6500}'::jsonb, '{"0":[9,13],"1":[9,13],"3":[9,13],"4":[9,13],"6":[14,18]}'::jsonb, 'Dr Eze focuses on women''s health, family planning and general check-ups, with a friendly, unhurried approach.', now(), true),
  ('yusuf-abdullahi', 'Dr Yusuf Abdullahi', 'General practitioner', 'doctor', 5, array['English', 'Hausa']::text[], array['general', 'heart', 'mens']::text[], array['video', 'voice', 'chat']::text[], '{"video":10000,"voice":8500,"chat":6000}'::jsonb, '{"1":[8,12],"2":[8,12],"3":[17,21],"4":[17,21],"5":[9,13]}'::jsonb, 'Dr Abdullahi helps with general health concerns, heart health and men''s health, and can explain test results in plain language.', now(), true),
  ('kemi-alade', 'Kemi Alade', 'Clinical psychologist', 'psychologist', 10, array['English', 'Yorùbá']::text[], array['anxiety', 'depression', 'stress']::text[], array['video', 'voice']::text[], '{"video":15000,"voice":13000,"chat":9000}'::jsonb, '{"0":[10,18],"2":[10,18],"4":[10,18]}'::jsonb, 'Kemi supports people through anxiety, low mood and stress, using evidence-based talking therapies in a safe, private space.', now(), true),
  ('emeka-nwosu', 'Emeka Nwosu', 'Counselling psychologist', 'psychologist', 7, array['English', 'Igbo', 'Pidgin']::text[], array['stress', 'relationships', 'eating']::text[], array['video', 'voice', 'chat']::text[], '{"video":13000,"voice":11000,"chat":8000}'::jsonb, '{"1":[12,20],"3":[12,20],"5":[10,16]}'::jsonb, 'Emeka helps with stress, relationship difficulties and a healthier relationship with food.', now(), true),
  ('bisi-oladipo', 'Bisi Oladipo', 'Certified fitness coach', 'coach', 6, array['English', 'Yorùbá']::text[], array['beginners', 'weight', 'strength']::text[], array['video', 'voice', 'chat']::text[], '{"video":6000,"voice":5000,"chat":3500}'::jsonb, '{"0":[6,10],"1":[6,10],"2":[6,10],"3":[6,10],"4":[6,10],"5":[7,11]}'::jsonb, 'Bisi builds simple home workouts for complete beginners: no gym, no equipment, just steady progress.', now(), true),
  ('musa-ibrahim', 'Musa Ibrahim', 'Certified fitness coach', 'coach', 4, array['English', 'Hausa', 'Pidgin']::text[], array['strength', 'older', 'beginners']::text[], array['video', 'voice', 'chat']::text[], '{"video":5500,"voice":4500,"chat":3000}'::jsonb, '{"1":[17,21],"3":[17,21],"5":[8,12],"6":[8,12]}'::jsonb, 'Musa helps people build strength safely, including older adults and those returning to exercise after a long break.', now(), true)
